// Request plumbing shared by the payments-* functions: CORS for the app's own
// origins, JSON answers with error codes, the signed-in caller, and turning a
// database refusal into the code the app translates.
import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2'
import type { Database } from './database.types.ts'

// Generated by `supabase gen types typescript --linked` (same command as the
// frontend's copy); regenerate both after every migration.
export type Db = SupabaseClient<Database>

/** An answer with a code for the app: { "error": "PAYMENT_NOT_NEEDED" }. */
export class HttpError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
  ) {
    super(code)
  }
}

export function requiredEnv(name: string): string {
  const value = Deno.env.get(name)
  if (!value) throw new HttpError(503, 'PAYMENTS_NOT_CONFIGURED')
  return value
}

// Browsers call payments-create / payments-verify directly from the app, so
// they need CORS. Only the app's own addresses are answered (ALLOWED_ORIGINS,
// comma-separated, per project), never any website.
function allowedOrigin(request: Request): string | null {
  const origin = request.headers.get('origin')
  const allowed = (Deno.env.get('ALLOWED_ORIGINS') ?? '').split(',').map((o) => o.trim())
  return origin && allowed.includes(origin) ? origin : null
}

export function corsHeaders(request: Request): Record<string, string> {
  const origin = allowedOrigin(request)
  return origin
    ? {
        'access-control-allow-origin': origin,
        'access-control-allow-headers': 'authorization, x-client-info, apikey, content-type',
        'access-control-allow-methods': 'POST, OPTIONS',
        vary: 'origin',
      }
    : { vary: 'origin' }
}

export function json(request: Request, status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json', ...corsHeaders(request) },
  })
}

export function serviceClient(): Db {
  return createClient<Database>(requiredEnv('SUPABASE_URL'), requiredEnv('SUPABASE_SERVICE_ROLE_KEY'), {
    auth: { persistSession: false, autoRefreshToken: false },
  })
}

/** The signed-in guest calling this function, checked with Supabase Auth. */
export async function callerId(request: Request, client: Db): Promise<string> {
  const token = request.headers.get('authorization')?.replace(/^Bearer\s+/i, '')
  if (!token) throw new HttpError(401, 'NOT_SIGNED_IN')
  const { data, error } = await client.auth.getUser(token)
  if (error || !data.user) throw new HttpError(401, 'NOT_SIGNED_IN')
  return data.user.id
}

// SQL functions raise a code as their message (ARCHITECTURE §2.5).
const SERVER_CODE = /^[A-Z][A-Z0-9_]+$/

/** A database refusal becomes a 409 with its code; anything else is a 500. */
export function fromDatabase(error: { message: string }): HttpError {
  return SERVER_CODE.test(error.message) ? new HttpError(409, error.message) : new HttpError(500, 'DATABASE_ERROR')
}

/** The common shape of every payments-* handler's error path. */
export function errorResponse(request: Request, name: string, error: unknown): Response {
  if (error instanceof HttpError) {
    if (error.status >= 500) console.error(`${name} error`, { code: error.code })
    return json(request, error.status, { error: error.code })
  }
  // Never log request bodies: they can hold payment ids and signatures.
  console.error(`${name} unexpected error`, { message: error instanceof Error ? error.message : String(error) })
  return json(request, 500, { error: 'UNEXPECTED' })
}
